import { useState } from "react";
import { CheckCircle2, ChevronRight, CircleAlert, FileText, Hammer, Layers3, PackageCheck } from "lucide-react";
import { useAuth } from "@/features/auth/AuthContext";
import { repo } from "@/data/repo";
import { useDb } from "@/data/store";
import * as act from "@/data/actions";
import { useAction } from "@/lib/useAction";
import { formatINR } from "@/lib/money";
import { uploadWorkspaceFile } from "@/lib/uploads";
import { EmptyState, PageHeader } from "@/components/app/Shell";
import { BoqItemBoard } from "@/components/app/BoqItemBoard";
import { PhotoCapture } from "@/components/app/SiteKit";
import type { TicketCause } from "@/types";

export default function VendorWorkPage() {
  useDb();
  const { user } = useAuth();
  const run = useAction();
  const [request, setRequest] = useState("");
  const [damageProject, setDamageProject] = useState("");
  if (!user) return null;
  const projects = repo.projects(user);
  const kits = repo.kits().filter((kit) => kit.active);

  return <>
    <PageHeader eyebrow="Franchisee workspace" title={`Welcome, ${user.name.split(" ")[0]}`} description="Your showroom, every item, every document and every delivery in one place." />
    {projects.length === 0 ? <EmptyState title="Your location is being set up" hint="Ola or Kurchi will add your showroom shortly." /> : <div className="space-y-5">{projects.map((project) => {
      const items = repo.itemsRaw(project.id);
      const invoices = repo.invoices(project.id);
      const documents = repo.documents(project.id);
      const consignments = repo.consignments(project.id);
      const value = items.reduce((sum, item) => sum + item.pricing.finalPrice * item.qty, 0);
      const required = project.advanceRequiredPct ?? 0;
      const received = project.advanceReceivedPct ?? 0;
      const advanceReady = received >= required;
      const delivered = items.filter((item) => ["DELIVERED_AT_SITE", "RECEIVED_OK", "INSTALLED", "HANDED_OVER"].includes(item.status)).length;
      const production = items.filter((item) => ["APPROVED", "IN_PRODUCTION", "PO_PLACED", "QC_PENDING", "READY_TO_PACK", "PACKED"].includes(item.status)).length;
      const pending = items.filter((item) => item.status === "DRAFT").length;
      const kyc = documents.filter((document) => ["KYC_GST", "KYC_MSME", "KYC_CANCELLED_CHEQUE"].includes(document.type));
      const productDocs = documents.filter((document) => ["DRAWING", "DESIGN_2D", "DESIGN_3D", "BROCHURE", "BOQ"].includes(document.type));

      return <section key={project.id} className="overflow-hidden rounded-3xl border bg-card">
        <div className="bg-primary px-5 py-5 text-primary-foreground sm:px-7"><p className="text-xs font-bold uppercase tracking-[.16em] text-primary-foreground/70">Your showroom</p><h2 className="mt-1 text-2xl font-extrabold">{project.site.city}</h2><p className="mt-1 text-sm text-primary-foreground/80">{project.site.address}</p></div>
        <div className="space-y-6 p-5 sm:p-7">
          <div className="grid gap-3 md:grid-cols-3"><Metric label="BOQ amount" value={formatINR(value)} /><Metric label="Advance received" value={`${received}%`} note={`of ${required}% required`} /><Metric label="Next status" value={advanceReady ? "Ready for production" : "Advance pending"} alert={!advanceReady} /></div>
          <section><div className="flex items-center gap-2"><PackageCheck className="h-5 w-5 text-primary"/><div><p className="eyebrow">Live order status</p><h3 className="font-extrabold">Every BOQ line, at a glance</h3></div></div><div className="mt-3 grid gap-2 sm:grid-cols-3"><Metric label="Delivered / installed" value={String(delivered)} /><Metric label="In production" value={String(production)} /><Metric label="Awaiting approval" value={String(pending)} /></div></section>
          <section className="grid gap-3 lg:grid-cols-[1fr_1.2fr]"><div className="rounded-2xl border bg-muted/35 p-4"><p className="eyebrow">Kurchi tax reference</p><h3 className="mt-1 font-extrabold">For your accounts team</h3><dl className="mt-4 space-y-2 text-sm"><div className="flex justify-between gap-3"><dt className="text-muted-foreground">Kurchi GSTIN</dt><dd className="font-bold">Shown on tax invoice</dd></div><div className="flex justify-between gap-3"><dt className="text-muted-foreground">Kurchi PAN</dt><dd className="font-bold">Shown on tax invoice</dd></div></dl></div><div className="rounded-2xl border bg-card p-4"><p className="eyebrow">Invoices</p><h3 className="mt-1 font-extrabold">Your showroom billing</h3>{invoices.length ? <div className="mt-3 space-y-2">{invoices.map((invoice) => <div key={invoice.id} className="flex items-center justify-between gap-3 rounded-xl bg-muted/55 px-3 py-2.5"><div><p className="font-mono text-sm font-bold">{invoice.number}</p><p className="mt-0.5 text-xs text-muted-foreground">{formatINR(invoice.netPayable)} · {invoice.status.replaceAll("_", " ").toLowerCase()}</p></div><span className="rounded-full bg-primary/10 px-2 py-1 text-xs font-bold text-primary">Available</span></div>)}</div> : <p className="mt-3 text-sm text-muted-foreground">No shipment invoice has been raised yet.</p>}</div></section>
          <div><BoqItemBoard items={items} title="Your BOQ - item by item" /></div>
          <section className="grid gap-3 lg:grid-cols-3"><DocumentGroup title="KYC documents" hint="GST, MSME and cancelled cheque" documents={kyc} /><DocumentGroup title="Product documents" hint="2D/3D drawings, brochure and BOQ" documents={productDocs} /><div className="rounded-2xl border bg-card p-4"><FileText className="h-5 w-5 text-primary"/><p className="eyebrow mt-3">Financial documents</p><h3 className="mt-1 font-extrabold">Invoices and deliveries</h3><p className="mt-2 text-sm text-muted-foreground">{invoices.length} invoice{invoices.length === 1 ? "" : "s"} · {consignments.length} shipment{consignments.length === 1 ? "" : "s"}</p><p className="mt-3 text-xs text-muted-foreground">Each partial shipment has its own invoice and delivery challan.</p></div></section>
          <KycUploader projectId={project.id} user={user} />
          <section className="rounded-2xl border border-primary/20 bg-primary/5 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-extrabold">Something arrived damaged?</p><p className="mt-1 text-sm text-muted-foreground">Send a photo report to Kurchi. A replacement follows the same production and delivery flow.</p></div><button type="button" onClick={() => setDamageProject(damageProject === project.id ? "" : project.id)} className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-extrabold text-primary-foreground"><CircleAlert className="h-4 w-4"/> Report damage</button></div>{damageProject === project.id && <FranchiseeDamageReport items={items} onSubmit={(value) => { const ok = run(() => act.fileTicket(user, { projectId: project.id, type: "DAMAGE", ...value }), "Damage report sent", "Kurchi will review the replacement."); if (ok) setDamageProject(""); }} />}</section>
          {!project.boqMode && <section><p className="eyebrow">Step 1</p><h3 className="mt-1 text-xl font-extrabold">Choose your BOQ</h3><div className="mt-4 grid gap-3 md:grid-cols-2"><button type="button" onClick={() => run(() => act.chooseFranchiseeBoq(user, project.id, { mode: "STANDARD", kitId: kits[0]?.id }), "Standard BOQ selected", "Review the scope below, then approve it.")} className="rounded-2xl border-2 border-primary bg-primary/5 p-5 text-left"><Layers3 className="h-7 w-7 text-primary"/><p className="mt-3 text-lg font-extrabold">Standard BOQ</p><p className="mt-1 text-sm text-muted-foreground">One fixed Kurchi package.</p><p className="mt-4 flex items-center gap-1 text-sm font-bold text-primary">Choose standard <ChevronRight className="h-4 w-4" /></p></button><button type="button" onClick={() => setRequest(project.id)} className="rounded-2xl border-2 p-5 text-left"><Hammer className="h-7 w-7 text-primary"/><p className="mt-3 text-lg font-extrabold">Modular BOQ</p><p className="mt-1 text-sm text-muted-foreground">Ask Kurchi to revise quantities from the catalogue.</p><p className="mt-4 flex items-center gap-1 text-sm font-bold text-primary">Request adjustment <ChevronRight className="h-4 w-4" /></p></button></div></section>}
          {project.boqMode === "MODULAR" && <div className="rounded-2xl border border-primary/25 bg-primary/5 p-4"><p className="font-extrabold">Your modular BOQ is with Kurchi</p><p className="mt-1 text-sm text-muted-foreground">{project.modularRequest}</p><p className="mt-2 text-xs font-bold text-primary">Accounts verification is required before production.</p></div>}
          {project.boqMode === "STANDARD" && <section><p className="eyebrow">Step 2</p><h3 className="mt-1 text-xl font-extrabold">Review and approve your BOQ</h3>{!project.franchiseeApprovedAt && <button type="button" onClick={() => run(() => act.approveBoq(user, project.id), "BOQ approved", "Kurchi Admin has been notified. Production can begin after Accounts verification.")} className="mt-4 inline-flex min-h-12 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-extrabold text-primary-foreground"><CheckCircle2 className="h-4 w-4"/> Approve BOQ</button>}{project.franchiseeApprovedAt && <p className="mt-4 inline-flex items-center gap-2 rounded-xl bg-red-100 px-3 py-2 text-sm font-bold text-red-900"><CheckCircle2 className="h-4 w-4"/> BOQ approved</p>}</section>}
          {request === project.id && <form onSubmit={(event) => { event.preventDefault(); const note = String(new FormData(event.currentTarget).get("request") ?? ""); const ok = run(() => act.chooseFranchiseeBoq(user, project.id, { mode: "MODULAR", request: note }), "Modular request sent", "Accounts will verify the revised commercial value before Kurchi starts work."); if (ok) setRequest(""); }} className="rounded-2xl border bg-muted/40 p-4"><p className="font-extrabold">Tell us the quantity changes</p><textarea required name="request" rows={3} placeholder="Example: Add two visitor chairs and remove one storage unit." className="mt-3 w-full rounded-xl border bg-background p-3 text-sm"/><button className="mt-3 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground">Send for verification</button></form>}
        </div>
      </section>;
    })}</div>}
  </>;
}

function Metric({ label, value, note, alert }: { label: string; value: string; note?: string; alert?: boolean }) { return <div className={`rounded-2xl border p-4 ${alert ? "border-amber-300 bg-amber-50" : "bg-muted/40"}`}><p className="eyebrow">{label}</p><p className="mt-2 text-xl font-extrabold">{value}</p>{note && <p className="mt-1 text-xs text-muted-foreground">{note}</p>}</div>; }
function DocumentGroup({ title, hint, documents }: { title: string; hint: string; documents: Array<{ id: string; name: string }> }) { return <div className="rounded-2xl border bg-card p-4"><FileText className="h-5 w-5 text-primary"/><p className="eyebrow mt-3">Documents</p><h3 className="mt-1 font-extrabold">{title}</h3><p className="mt-1 text-sm text-muted-foreground">{documents.length ? documents.map((document) => document.name).join(", ") : hint}</p></div>; }
function KycUploader({ projectId, user }: { projectId: string; user: NonNullable<ReturnType<typeof useAuth>["user"]> }) {
  const run = useAction();
  const [type, setType] = useState<"KYC_GST" | "KYC_MSME" | "KYC_CANCELLED_CHEQUE">("KYC_GST");
  const [uploading, setUploading] = useState(false);
  return <section className="rounded-2xl border bg-card p-4"><p className="eyebrow">KYC upload</p><h3 className="mt-1 font-extrabold">Add franchisee documents</h3><p className="mt-1 text-sm text-muted-foreground">Upload GST, MSME or cancelled cheque against this showroom.</p><div className="mt-3 flex flex-wrap gap-2"><select value={type} onChange={(event) => setType(event.target.value as typeof type)} className="min-h-11 rounded-xl border bg-background px-3 text-sm font-semibold"><option value="KYC_GST">GST certificate</option><option value="KYC_MSME">MSME certificate</option><option value="KYC_CANCELLED_CHEQUE">Cancelled cheque</option></select><label className="inline-flex min-h-11 cursor-pointer items-center rounded-xl bg-primary px-4 text-sm font-extrabold text-primary-foreground">{uploading ? "Uploading…" : "Choose file"}<input type="file" accept="image/*,.pdf" className="sr-only" onChange={async (event) => { const file = event.target.files?.[0]; if (!file) return; setUploading(true); try { const fileUrl = await uploadWorkspaceFile(file, `kyc/${projectId}`); run(() => act.addDocument(user, { id: `doc-${Date.now()}`, projectId, type, name: file.name, addedBy: user.name, addedAt: new Date().toISOString(), fileUrl }), "KYC document added"); } finally { setUploading(false); event.currentTarget.value = ""; } }} /></label></div></section>;
}
function FranchiseeDamageReport({ items, onSubmit }: { items: Array<{ id: string; name: string; qty: number }>; onSubmit: (value: { itemId: string; qtyAffected: number; cause: TicketCause; photos: string[]; note: string }) => void }) { const [itemId, setItemId] = useState(items[0]?.id ?? ""); const [qty, setQty] = useState(1); const [note, setNote] = useState(""); const [photos, setPhotos] = useState<string[]>([]); return <div className="mt-4 border-t border-primary/15 pt-4"><div className="grid gap-2 sm:grid-cols-2"><select value={itemId} onChange={(event) => setItemId(event.target.value)} className="min-h-11 rounded-xl border bg-background px-3 text-sm font-semibold">{items.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><input type="number" min={1} value={qty} onChange={(event) => setQty(Math.max(1, Number(event.target.value) || 1))} className="min-h-11 rounded-xl border bg-background px-3 text-sm" /></div><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="What is damaged?" className="mt-2 w-full rounded-xl border bg-background p-3 text-sm"/><div className="mt-2"><PhotoCapture photos={photos} required label="Add damage photo" onAdd={(photo) => setPhotos((current) => [...current, photo ?? `franchisee-damage-${current.length + 1}.jpg`])} onRemove={(index) => setPhotos((current) => current.filter((_, currentIndex) => currentIndex !== index))}/></div><button type="button" disabled={!itemId || !note.trim() || !photos.length} onClick={() => onSubmit({ itemId, qtyAffected: qty, cause: "TRANSIT", photos, note })} className="mt-3 min-h-11 rounded-xl bg-primary px-4 text-sm font-extrabold text-primary-foreground disabled:opacity-40">Send damage report</button></div>; }
